import type { ReactNode } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface FloatingButtonGroupAction {
  type?: "action";
  id: string;
  label: string;
  icon?: ReactNode;
  iconOnly?: boolean;
  onSelect?: () => void;
  disabled?: boolean;
  pressed?: boolean;
  shortcut?: string;
}

export interface FloatingButtonGroupSeparator {
  type: "separator";
  id?: string;
}

export type FloatingButtonGroupItem = FloatingButtonGroupAction | FloatingButtonGroupSeparator;

export interface FloatingButtonGroupProps extends Omit<ViewProps, "children"> {
  items: FloatingButtonGroupItem[];
  label: string;
  variant?: "muted" | "floating";
  size?: "sm" | "md";
  orientation?: "horizontal" | "vertical";
  iconOnly?: boolean;
  onAction?: (id: string) => void;
  /** Extend the inner, named parts of the group: button, buttonText or separator. The React Native counterpart of `classNames`. */
  styles?: {
    button?: StyleProp<ViewStyle>;
    buttonText?: StyleProp<TextStyle>;
    separator?: StyleProp<ViewStyle>;
  };
}

/** A pill of tools that floats over content, such as a canvas toolbar. */
export function FloatingButtonGroup({ items, label, variant = "muted", size = "md", orientation = "horizontal", iconOnly: groupIconOnly = false, onAction, style, styles: parts, ...props }: FloatingButtonGroupProps) {
  const tokens = useTokens();
  const vertical = orientation === "vertical";
  const height = size === "sm" ? 32 : 40;

  return (
    <View
      {...props}
      accessibilityRole="toolbar"
      accessibilityLabel={label}
      style={[
        local.root,
        { flexDirection: vertical ? "column" : "row", borderColor: tokens.border, backgroundColor: variant === "floating" ? tokens.surface : tokens.surfaceMuted },
        variant === "floating" && local.shadow,
        style,
      ]}
    >
      {items.map((item, index) => {
        if (item.type === "separator") {
          return <View key={item.id ?? `sep-${index}`} style={[vertical ? local.hr : local.vr, { backgroundColor: tokens.border }, parts?.separator]} />;
        }
        const iconOnly = groupIconOnly || item.iconOnly;
        return (
          <Pressable
            key={item.id}
            accessibilityRole="button"
            accessibilityLabel={item.label}
            accessibilityState={{ disabled: item.disabled, selected: item.pressed }}
            disabled={item.disabled}
            onPress={() => {
              item.onSelect?.();
              onAction?.(item.id);
            }}
            style={({ pressed }) => [
              local.button,
              { minHeight: height, minWidth: iconOnly ? height : undefined, backgroundColor: item.pressed ? tokens.surface : pressed ? tokens.border : "transparent", opacity: item.disabled ? 0.45 : 1 },
              parts?.button,
            ]}
          >
            {item.icon}
            {iconOnly ? null : <Text style={[{ color: tokens.foreground, fontSize: metrics.text.sm, fontWeight: "500" }, parts?.buttonText]}>{item.label}</Text>}
            {item.shortcut && !iconOnly ? <Text style={{ color: tokens.textMuted, fontSize: metrics.text.xs }}>{item.shortcut}</Text> : null}
          </Pressable>
        );
      })}
    </View>
  );
}

const local = StyleSheet.create({
  root: { alignSelf: "flex-start", alignItems: "center", gap: 2, padding: 3, borderWidth: 1, borderRadius: 999 },
  shadow: { shadowColor: "#000", shadowOpacity: 0.14, shadowRadius: 14, shadowOffset: { width: 0, height: 6 }, elevation: 6 },
  button: { flexDirection: "row", alignItems: "center", justifyContent: "center", gap: 6, paddingHorizontal: 12, borderRadius: 999 },
  vr: { width: 1, height: 18, marginHorizontal: 4 },
  hr: { height: 1, width: 18, marginVertical: 4 },
});

export default FloatingButtonGroup;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}
